-- 운영 이전부터 있던 local_jobs 기반 열의 시험용 정의(대표 2026-11-26 '기반 스키마 교정'). 시험 서버(pg-chain BASE)와 격리 실제 스택(isolated-stack-e2e)이 같은 파일을 쓴다.
-- 근거: 운영 구조 지문(Lee 실행 45828209586)과 열 단위 대조 — 타입·널 허용은 운영 그대로(title·company NOT NULL, lat·lng numeric, num_hires text, active는 널 허용+기본 true).
-- 기본값은 글자 대신 md5 지문만 읽었으므로, 운영 지문과 같은 값만 넣었다: category 'other'::text · urgent false · posted_at CURRENT_DATE · company_verified false · active true.
-- updated_at은 운영에서 20261025160000이 나중에 더한 열(기본값 없음·널 허용)이라 기반에 두지 않는다(격리 실제 스택 구조 대조에서 확인).
-- origin은 0009의 649건 확인 절을 건너뛰게 미리 둔다(빈 시험 DB라 건수 조건을 못 맞춘다). 아래 뒤쪽 열은 첫 migration들이 이미 있다고 전제하는 운영 이전 열이다.
create table public.local_jobs (id bigint generated by default as identity primary key, title text not null, company text not null, category text default 'other'::text, salary text, location text, hours text,
  employer_phone text, application_deadline date, urgent boolean default false, description text, posted_at date default CURRENT_DATE, lat numeric, lng numeric,
  active boolean default true, image_url text, created_at timestamptz default now(),
  employer_id uuid references auth.users(id), origin text not null default 'legacy', admin_hidden boolean not null default false,
  work_period text, publish_gate_reason text, source text, source_url text, work_days text, images jsonb, education text, contact_zalo text, preference text,
  num_hires text, company_verified boolean default false, company_founded_year integer, hire_count integer);
alter table public.local_jobs enable row level security;
grant select on public.local_jobs to anon, authenticated;
